<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api} from './api';
import RolePermissions from './RolePermissions.vue';
interface User {id:string;login:string;displayName:string;role:'Administrator'|'Operator'|'Viewer';enabled:boolean;securityVersion:number}
const props=defineProps<{admin:boolean;currentAccountId:string}>();
const emit=defineEmits<{signedOut:[]}>();const users=ref<User[]>([]),draft=ref<User|null>(null),newPassword=ref(''),oldPassword=ref(''),ownPassword=ref(''),changeOwn=ref(false),isNew=ref(false),busy=ref(false),error=ref(''),message=ref('');
const names={Administrator:'管理员',Operator:'操作员',Viewer:'浏览员'};
async function load(){if(props.admin)users.value=await api('/api/users')}
function open(u?:User){draft.value=u?{...u}:{id:'',login:'',displayName:'',role:'Operator',enabled:true,securityVersion:0};isNew.value=!u;newPassword.value='';error.value=''}
async function save(){if(!draft.value||busy.value)return;busy.value=true;try{const {id,...u}=draft.value;await api('/api/users'+(isNew.value?'':'/'+id),isNew.value?'POST':'PUT',{...u,newPassword:newPassword.value||null});draft.value=null;if(id===props.currentAccountId){emit('signedOut');return}message.value='账号已保存；被修改账号的原登录会话已失效，请重新登录。';await load()}catch(e){error.value=String(e)}finally{newPassword.value='';busy.value=false}}
async function password(){busy.value=true;try{await api('/api/auth/password','POST',{currentPassword:oldPassword.value,newPassword:ownPassword.value});oldPassword.value='';ownPassword.value='';changeOwn.value=false;emit('signedOut')}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>void load().catch(e=>error.value=String(e)));
</script>
<template><section class="panel panel-body"><div class="toolbar"><h2>账号与岗位权限</h2><div class="inline-actions"><button class="button" @click="changeOwn=true;oldPassword='';ownPassword='';error=''">修改本人密码</button><button v-if="admin" class="button primary" @click="open()">新增账号</button></div></div><p class="help">各岗位的功能权限在下方矩阵设置。停用、改角色或改密码后，原登录会话立即失效。</p><p v-if="error&&!draft&&!changeOwn" role="alert" class="error-message">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><table v-if="admin"><thead><tr><th>登录账号</th><th>姓名</th><th>岗位</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.login}}</td><td>{{u.displayName}} {{u.id===currentAccountId?'（本人）':''}}</td><td>{{names[u.role]}}</td><td>{{u.enabled?'启用':'停用'}}</td><td><button class="text-button" @click="open(u)">编辑账号</button></td></tr></tbody></table></section><RolePermissions v-if="admin"/><div v-if="draft||changeOwn" class="modal-backdrop"><section class="modal" role="dialog" :aria-label="changeOwn?'修改本人密码':'编辑账号'"><div class="modal-head"><h2>{{changeOwn?'修改本人密码':isNew?'新增账号':'编辑账号'}}</h2><button class="button" @click="draft=null;changeOwn=false;newPassword='';oldPassword='';ownPassword=''">关闭</button></div><div class="modal-body"><p v-if="error" role="alert" class="error-message">{{error}}</p><form v-if="draft" class="config-fields" @submit.prevent="save"><label class="config-field">登录账号<input v-model="draft.login" :readonly="!isNew" pattern="[A-Za-z0-9_-]{3,60}" required autocomplete="off"></label><label class="config-field">姓名<input v-model="draft.displayName" required maxlength="80"></label><label class="config-field">岗位<select v-model="draft.role" aria-label="账号岗位" :disabled="draft.id===currentAccountId"><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select></label><label class="config-field">{{isNew?'初始密码':'重设密码（留空保持原密码）'}}<input v-model="newPassword" type="password" :required="isNew" minlength="8" maxlength="128" autocomplete="new-password"></label><label class="checkbox"><input v-model="draft.enabled" type="checkbox" :disabled="draft.id===currentAccountId">启用账号</label><p class="help wide-field">登录名创建后不修改；账号停用保留已有记录。至少保留一个启用的管理员。</p><button class="button primary" :disabled="busy">保存账号</button></form><form v-else class="config-fields" @submit.prevent="password"><label class="config-field">当前密码<input v-model="oldPassword" type="password" required maxlength="128" autocomplete="current-password"></label><label class="config-field">新密码<input v-model="ownPassword" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><button class="button primary" :disabled="busy">修改并重新登录</button></form></div></section></div></template>
